deploy_hash_function_codes.Root:
function handler(event) {
            var request = event.request;
            var prefix = '/';
            // viewer が同名 header を送ってもキャッシュキーに使わせない
            delete request.headers['x-pocket-deploy-hash'];
            if (request.uri.indexOf(prefix) === 0) {
                var rest = request.uri.substring(prefix.length);
                var slash = rest.indexOf('/');
                if (slash > 0) {
                    var segment = rest.substring(0, slash);
                    if (/^[0-9a-f]{7,40}$/.test(segment) || segment === "unknown") {
                        request.uri = prefix + rest.substring(slash + 1);
                        // URI から外した hash をキャッシュキーに残す (CachePolicy が参照する)
                        request.headers['x-pocket-deploy-hash'] = { value: segment };
                    }
                }
            }
            return request;
        }

cache_control_function_codes.Root:
function handler(event) {
            var response = event.response;
            var status = response.statusCode;
            if ((status >= 200 && status < 300) || status === 304) {
                response.headers['cache-control'] = { value: 'public, max-age=31536000, immutable' };
            }
            return response;
        }
